class MovingAverage {
  private all: number[] = [];
  constructor(private size: number) {}

  next(val: number): number {
    this.all.push(val);
    const from = Math.max(0, this.all.length - this.size);
    let sum = 0;
    for (let i = from; i < this.all.length; i++) sum += this.all[i];
    return sum / (this.all.length - from);
  }
}

