class MovingAverage {
  private buf: number[];
  private pos = 0;
  private count = 0;
  private sum = 0;

  constructor(private size: number) {
    this.buf = new Array(size).fill(0);
  }

  next(val: number): number {
    if (this.count === this.size) this.sum -= this.buf[this.pos]; // oldest leaves
    else this.count++;
    this.buf[this.pos] = val;
    this.sum += val;
    this.pos = (this.pos + 1) % this.size;
    return this.sum / this.count;
  }
}

